INSERT OR REPLACE INTO faqs (id, question, answer, category, is_published, sort_order, created_at, updated_at) VALUES ('1', 'How long does recovery take?', 'Typically 2-4 weeks.', 'general', 1, 1, '2026-04-26T11:05:50.722Z', '2026-04-26T11:05:50.722Z');
INSERT OR REPLACE INTO faqs (id, question, answer, category, is_published, sort_order, created_at, updated_at) VALUES ('74ba7250-161b-426d-981b-7c2af805d5b1', 'How can I recover scammed cryptocurrency in the USA?', 'In the USA, recovering stolen Bitcoin or Ethereum requires a combination of forensic blockchain analysis and coordination with the FBI''s IC3 and local law enforcement. ChanAidRecovery Hub provides the forensic reports necessary to initiate these actions and works with legal partners to secure asset freeze orders.', 'GEO-USA', 1, 0, '2026-04-27T01:31:19.863Z', '2026-04-27T01:31:19.863Z');
INSERT OR REPLACE INTO faqs (id, question, answer, category, is_published, sort_order, created_at, updated_at) VALUES ('32d80625-7109-4b5e-aa39-8a01308a53f7', 'Is it possible to get back stolen Bitcoin in the UK?', 'Yes. The UK has robust legal frameworks for asset recovery. We utilize Action Fraud standards and high-court injunctions (Mareva injunctions) to freeze stolen assets once they hit UK-linked exchanges or bank accounts.', 'GEO-UK', 1, 1, '2026-04-27T01:31:19.889Z', '2026-04-27T01:31:19.889Z');
INSERT OR REPLACE INTO faqs (id, question, answer, category, is_published, sort_order, created_at, updated_at) VALUES ('b9fa51a6-3b33-4859-acd4-1c5476cca2ac', 'What is the success rate for crypto recovery in Australia?', 'Our success rate in Australia is over 93%. We work closely with AFCA standards and utilize advanced chain-analysis to track funds through Australian exchanges, ensuring that scammed citizens have the best chance of restitution.', 'GEO-AU', 1, 2, '2026-04-27T01:31:19.943Z', '2026-04-27T01:31:19.943Z');
INSERT OR REPLACE INTO faqs (id, question, answer, category, is_published, sort_order, created_at, updated_at) VALUES ('69aba0e3-148e-4976-9dc5-2e7064a44968', 'Can scammed funds be recovered in Canada?', 'Canadian residents targeted by investment scams can leverage our forensic expertise. We track the ''money trail'' through global exchanges and provide the evidence needed for FINTRAC reporting and civil recovery litigation.', 'GEO-CA', 1, 3, '2026-04-27T01:31:19.959Z', '2026-04-27T01:31:19.959Z');
INSERT OR REPLACE INTO faqs (id, question, answer, category, is_published, sort_order, created_at, updated_at) VALUES ('9c263a5b-aced-40d7-bd5d-6e9123751aab', 'How do I report a crypto scam in Dubai/UAE?', 'Dubai and the UAE have strict cybercrime laws. ChanAidRecovery Hub assists UAE residents by preparing technical evidence for the Dubai Police Cybercrime department and identifying the off-ramp points in Middle Eastern exchanges.', 'GEO-UAE', 1, 4, '2026-04-27T01:31:19.965Z', '2026-04-27T01:31:19.965Z');
